// Extract AfterShip payload and filter to key statuses only
const body = $input.first().json.body || $input.first().json;
const msg = body.msg || {};
const tag = msg.tag || '';

// Only send updates for these statuses
const KEY_STATUSES = ['InTransit', 'OutForDelivery', 'Delivered', 'AttemptFail', 'Exception', 'AvailableForPickup'];

if (!KEY_STATUSES.includes(tag)) {
  // Not a key status — stop processing silently
  return [];
}

const trackingNumber = (msg.tracking_number || '').toString().trim();
if (!trackingNumber) return [];

const checkpoint = msg.last_checkpoint || {};
const eta = msg.estimated_delivery_date?.datetime || '';

return [{
  json: {
    tracking_number: trackingNumber,
    tag: tag,
    last_message: checkpoint.message || '',
    last_location: checkpoint.location || '',
    last_time: checkpoint.checkpoint_time || '',
    eta: eta
  }
}];

// Extract customer phone from Monday result
const data = $input.first().json.data || {};
const items = data.items_page_by_column_values?.items || [];

if (!items.length) return []; // Order not found

const item = items[0];
const phoneCol = (item.column_values || []).filter(c => c.id === 'phone__1')[0];
const rawPhone = phoneCol?.text || '';

// Normalize phone: strip everything except digits
const phone = rawPhone.replace(/[^0-9]/g, '');
if (!phone) return []; // No phone on record

// Get tracking context from previous node
const tracking = $('Extract & Filter').first().json;

return [{
  json: {
    phone: phone,
    customer_name: item.name,
    tracking_number: tracking.tracking_number,
    tag: tracking.tag,
    last_message: tracking.last_message,
    last_location: tracking.last_location,
    eta: tracking.eta
  }
}];

const { tag, last_message, last_location, eta, phone, tracking_number, customer_name } = $input.first().json;

const warNotice = 'בעקבות מבצע שאגת הארי צפויים עיכובים קלים במשלוחים, אנחנו עם יד על הדופק ובודקים מה עם המשלוח שלך בכל יום ויום.\nנא להיות סבלניים 🙏';

const statusMap = {
  InTransit: { headline: 'בדרכה לארץ! ✈️', detail: 'זמני האספקה הם 7-21 ימי עסקים, אנו נעדכן אותכם בכל שלב ושלב.' },
  OutForDelivery: { headline: 'יוצאת למסירה עכשיו! 🚚', detail: 'השליח בדרכו אליך היום — שמור על הטלפון פתוח!' },
  Delivered: { headline: 'נמסרה! 🎉', detail: 'ההזמנה שלך נמסרה בהצלחה!\nנשמח לשמוע שהגיעה — תהנה מהמוצר! ⚽' },
  AttemptFail: { headline: 'ניסיון מסירה נכשל ⚠️', detail: 'לא הצלחנו למסור את החבילה. ננסה שוב בהקדם.' },
  Exception: { headline: 'בעיה במשלוח ⚠️', detail: 'אנחנו בודקים מה קורה ונחזור אליך בהקדם.' },
  AvailableForPickup: { headline: 'מחכה לך בנקודת חלוקה 📍', detail: 'החבילה שלך מחכה לאיסוף בנקודת החלוקה הקרובה אליך.' }
};

const info = statusMap[tag];
if (!info) return [];

let etaLine = '';
if (eta) {
  try {
    const d = new Date(eta);
    const formatted = d.toLocaleDateString('he-IL', { weekday: 'long', day: 'numeric', month: 'long' });
    etaLine = `\nצפי הגעה: ${formatted}`;
  } catch(e) {
    etaLine = `\nצפי הגעה: ${eta}`;
  }
}

const firstName = (customer_name || '').split(' ')[0];
const greeting = firstName ? `שלום ${firstName}! 👋\n\n` : '';
const war = (tag !== 'Delivered') ? `\n\n${warNotice}` : '';
const trackingLink = `\n\n🔍 *למעקב עצמאי בכל רגע:* https://www.hfd.co.il/איתור-חבילה/\n_(יש להקליד את מספר המעקב ידנית)_`;

const message = `*עדכון משלוח | OneZone* 🏆\n\n${greeting}*סטטוס:* ${info.headline}\n\n${info.detail}${etaLine}${war}\n\n*מס׳ מעקב:* ${tracking_number}${trackingLink}\n\n_להפסקת עדכונים שלח STOP_`;

return [{ json: { phone, message } }];
